  function moveInArray(arr, index, dir){
    const newIndex = index + dir;
    if(newIndex < 0 || newIndex >= arr.length) return arr;
    const copy = arr.slice();
    [copy[index], copy[newIndex]] = [copy[newIndex], copy[index]];
    return copy;
  }

  function renderOrderList(containerId, order, labels, onChange){
    const el = document.getElementById(containerId);
    el.innerHTML = order.map((key,i)=>`
      <div class="admin-item">
        <span style="flex:1;">${labels[key]||key}</span>
        <button type="button" class="logout-btn" data-move="up" data-idx="${i}" ${i===0?'disabled':''} style="padding:6px 12px;">↑</button>
        <button type="button" class="logout-btn" data-move="down" data-idx="${i}" ${i===order.length-1?'disabled':''} style="padding:6px 12px;">↓</button>
      </div>`).join('');
    el.querySelectorAll('button[data-move]').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const idx = parseInt(btn.dataset.idx,10);
        const dir = btn.dataset.move==='up' ? -1 : 1;
        onChange(moveInArray(order, idx, dir));
      });
    });
  }

