  /* ============ COMPTEUR DE VISITES DU SITE ============ */
  async function trackSiteVisit(){
    if(sessionStorage.getItem('cst_visit_counted')==='1') return;
    sessionStorage.setItem('cst_visit_counted','1');
    try{
      const { data, error } = await sb.rpc('increment_visits');
      if(!error && typeof data === 'number'){
        document.getElementById('statVisits').textContent = formatViews(data);
        siteVisits = data;
        renderKpis();
      }
    }catch(e){ /* si la fonction increment_visits n'existe pas encore côté Supabase, on ignore silencieusement */ }
  }
  async function loadSiteVisits(){
    const raw = await storeGet('site_visits');
    siteVisits = raw ? Number(raw)||0 : 0;
    document.getElementById('statVisits').textContent = formatViews(siteVisits);
  }
  function renderKpis(){
    document.getElementById('kpiVideos').textContent = videos.length;
    document.getElementById('kpiArticles').textContent = articles.length;
    document.getElementById('kpiViews').textContent = formatViews(videos.reduce((s,v)=>s+(v.views||0),0));
    document.getElementById('kpiVisits').textContent = formatViews(siteVisits);
  }

