  document.getElementById('loginForm').addEventListener('submit', (e)=>{
    e.preventDefault();
    const errEl = document.getElementById('loginErr');
    const lockUntil = Number(sessionStorage.getItem('cst_lock_until')||0);
    if(Date.now() < lockUntil){
      const secs = Math.ceil((lockUntil-Date.now())/1000);
      errEl.textContent = `Trop de tentatives. Réessayez dans ${secs}s.`;
      return;
    }
    const email = document.getElementById('loginEmail').value.trim().toLowerCase();
    const pw = document.getElementById('loginPassword').value;
    const remember = document.getElementById('rememberMe').checked;
    if(email === ADMIN_EMAIL.toLowerCase() && pw === ADMIN_PASSWORD){
      sessionStorage.removeItem('cst_login_fails');
      sessionStorage.removeItem('cst_lock_until');
      (remember ? localStorage : sessionStorage).setItem('cst_admin_session','1');
      updateAdminBadge();
      closeGate();
      document.getElementById('loginForm').reset();
      showView('admin');
      const toast = document.getElementById('loginToast');
      toast.classList.add('show');
      setTimeout(()=> toast.classList.remove('show'), 2500);
    } else {
      const fails = Number(sessionStorage.getItem('cst_login_fails')||0) + 1;
      sessionStorage.setItem('cst_login_fails', String(fails));
      if(fails >= 5){
        sessionStorage.setItem('cst_lock_until', String(Date.now() + 30000));
        sessionStorage.removeItem('cst_login_fails');
        errEl.textContent = 'Trop de tentatives. Réessayez dans 30s.';
      } else {
        errEl.textContent = `E-mail ou mot de passe incorrect. (${fails}/5)`;
      }
    }
  });
