  function applyStatusUXNoDateReset(status, hintId){
    const hint = document.getElementById(hintId);
    const dateInput = document.getElementById(hintId==='statusHint' ? 'publishedAt' : 'articlePublishedAt');
    if(dateInput) dateInput.closest('.field').style.display = (status==='scheduled') ? 'block' : 'none';
    if(status==='published') hint.textContent = 'Visible sur le site.';
    else if(status==='scheduled') hint.textContent = 'Choisissez le jour et l\'heure exacts ci-dessus : la publication restera cachée jusqu\'à ce moment précis, puis apparaîtra automatiquement sur le site — sans action de votre part.';
    else hint.textContent = 'Reste privé, non visible sur le site. Retrouvez-le dans l\'onglet "Brouillons" pour le publier ou le programmer plus tard.';
  }
  function applyStatusUX(status, dateFieldId, hintId){
    const dateInput = document.getElementById(dateFieldId);
    const hint = document.getElementById(hintId);
    dateInput.closest('.field').style.display = (status==='scheduled') ? 'block' : 'none';
    if(status==='published'){
      const now = new Date(); now.setMinutes(now.getMinutes()-now.getTimezoneOffset());
      dateInput.value = now.toISOString().slice(0,16);
      hint.textContent = 'Sera visible sur le site immédiatement après validation.';
    } else if(status==='scheduled'){
      const cur = dateInput.value ? new Date(dateInput.value) : null;
      if(!cur || cur <= new Date()){
        const future = new Date(Date.now()+3600000); future.setMinutes(future.getMinutes()-future.getTimezoneOffset());
        dateInput.value = future.toISOString().slice(0,16);
      }
      hint.textContent = 'Choisissez ci-dessus le jour et l\'heure exacts : la publication restera cachée jusqu\'à ce moment précis, puis apparaîtra automatiquement sur le site — sans action de votre part.';
    } else {
      hint.textContent = 'Reste privé, non visible sur le site. Retrouvez-le dans l\'onglet "Brouillons" pour le publier ou le programmer plus tard.';
    }
  }

  /* ============ PLATEFORMES ============ */
  function isSafeUrl(url){ return /^https:\/\//i.test(url.trim()) || /^http:\/\//i.test(url.trim()); }
  function detectPlatform(url){
    if(!isSafeUrl(url)) return null;
    if(/tiktok\.com/.test(url)) return 'tiktok';
    if(/instagram\.com/.test(url)) return 'instagram';
    if(/facebook\.com|fb\.watch/.test(url)) return 'facebook';
    if(url.trim()) return 'autre';
    return null;
  }
  const platformLabel = {tiktok:'TikTok', instagram:'Instagram', facebook:'Facebook', autre:'Lien externe', upload:'Vidéo'};
  let linkCoverManual = null;   // image choisie à la main par l'admin
  let linkCoverAuto = null;     // vignette récupérée automatiquement (TikTok uniquement)
  let tiktokFetchTimer = null;

  document.getElementById('videoUrl').addEventListener('input', (e)=>{
    const url = e.target.value;
    const p = detectPlatform(url);
    document.getElementById('platformTag').textContent = p ? 'Plateforme détectée : '+platformLabel[p] : '';
    linkCoverAuto = null;
    clearTimeout(tiktokFetchTimer);
    if(p==='tiktok'){
      tiktokFetchTimer = setTimeout(async ()=>{
        try{
          const res = await fetch('https://www.tiktok.com/oembed?url='+encodeURIComponent(url));
          if(res.ok){ const data = await res.json(); if(data.thumbnail_url) linkCoverAuto = data.thumbnail_url; }
        }catch(err){ /* pas d'accès direct (CORS) — on garde le visuel générique ou l'image manuelle */ }
      }, 500);
    }
  });
  document.getElementById('coverInput').addEventListener('change', ()=>{
    const f = document.getElementById('coverInput').files[0];
    if(!f) return;
    const r = new FileReader();
    r.onload = ()=>{ linkCoverManual = r.result; document.getElementById('coverName').textContent = 'Sélectionnée : '+f.name; };
    r.readAsDataURL(f);
  });

  function embedForLink(url, platform){
    if(platform==='tiktok'){ const m=url.match(/video\/(\d+)/); if(m) return `<iframe src="https://www.tiktok.com/embed/v2/${m[1]}" allow="encrypted-media" loading="lazy"></iframe>`; }
    if(platform==='instagram'){ const m=url.match(/\/(p|reel|reels)\/([A-Za-z0-9_-]+)/); if(m) return `<iframe src="https://www.instagram.com/${m[1]}/${m[2]}/embed" allow="encrypted-media" loading="lazy"></iframe>`; }
    if(platform==='facebook'){ return `<iframe src="https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(url)}&show_text=false" allow="encrypted-media" loading="lazy"></iframe>`; }
    return `<a href="${url}" target="_blank" style="display:flex;align-items:center;justify-content:center;height:100%;color:#fff;font-size:11px;text-align:center;padding:10px;">Voir la publication ↗</a>`;
  }

  /* ============ COMPRESSION AUTOMATIQUE DES VIDÉOS (ffmpeg.wasm, dans le navigateur) ============
     Réduit la résolution/le débit des vidéos trop lourdes avant l'envoi vers le stockage,
     pour gagner de la place sans dégrader visiblement la qualité. Si la compression échoue
     (pas de connexion au CDN, fichier déjà optimisé, etc.), le fichier original est utilisé
     tel quel — la publication n'est jamais bloquée par cette étape.  */
  let ffmpegInstance = null;
  async function getFFmpeg(){
    if(ffmpegInstance) return ffmpegInstance;
    if(typeof FFmpeg === 'undefined') throw new Error('ffmpeg.wasm non chargé');
    const { createFFmpeg } = FFmpeg;
    ffmpegInstance = createFFmpeg({ log:false, corePath:'https://unpkg.com/@ffmpeg/core@0.11.0/dist/ffmpeg-core.js' });
    await ffmpegInstance.load();
    return ffmpegInstance;
  }
  async function compressVideo(file, onProgress){
    // Fichiers déjà légers : pas la peine d'attendre une compression pour gagner peu.
    if(file.size < 15*1024*1024) return file;
    try{
      const ffmpeg = await getFFmpeg();
      const { fetchFile } = FFmpeg;
      const stamp = Date.now();
      const inputName = 'in_'+stamp+'.mp4';
      const outputName = 'out_'+stamp+'.mp4';
      ffmpeg.FS('writeFile', inputName, await fetchFile(file));
      ffmpeg.setProgress(({ ratio })=>{ if(onProgress && ratio>=0 && ratio<=1) onProgress(Math.round(ratio*100)); });
      // Limite la résolution à 1280px de large max, débit vidéo ajusté par CRF (qualité quasi
      // identique à l'œil), audio ré-encodé en AAC 128k : bon compromis poids/qualité.
      await ffmpeg.run(
        '-i', inputName,
        '-vf', "scale='min(1280,iw)':-2",
        '-c:v', 'libx264', '-crf', '26', '-preset', 'veryfast',
        '-c:a', 'aac', '-b:a', '128k',
        '-movflags', '+faststart',
        outputName
      );
      const data = ffmpeg.FS('readFile', outputName);
      try{ ffmpeg.FS('unlink', inputName); ffmpeg.FS('unlink', outputName); }catch(e){}
      const compressedBlob = new Blob([data.buffer], { type:'video/mp4' });
      if(compressedBlob.size >= file.size) return file; // pas d'amélioration, on garde l'original
      return new File([compressedBlob], file.name.replace(/\.\w+$/,'')+'.mp4', { type:'video/mp4' });
    }catch(e){
      console.error('compressVideo: échec, fichier original conservé', e);
      return file;
    }
  }

  /* ============ IMPORT FICHIER : durée + vignette auto (évite les images noires) ============ */
  const fileInput = document.getElementById('fileInput');
  fileInput.addEventListener('change', async ()=>{
    let f = fileInput.files[0];
    if(!f) return;
    if(f.size > 500*1024*1024){ document.getElementById('fileName').textContent='Fichier trop volumineux (max 500 Mo).'; fileData=null; return; }
    const originalSize = f.size;
    document.getElementById('fileName').textContent = 'Compression de la vidéo…';
    f = await compressVideo(f, (pct)=>{ document.getElementById('fileName').textContent = `Compression… ${pct}%`; });
    document.getElementById('fileName').textContent = f.size < originalSize
      ? `Compression terminée (-${Math.round((1 - f.size/originalSize)*100)}%) — analyse…`
      : 'Analyse du fichier…';
    const objectUrl = URL.createObjectURL(f);
    const vid = document.createElement('video');
    vid.src = objectUrl; vid.muted = true; vid.playsInline = true;

    // Points à essayer, dans l'ordre, jusqu'à trouver une image qui n'est pas noire/trop sombre.
    // On part de la 20e seconde par défaut (souvent après un fondu d'ouverture), puis on
    // recule/avance si besoin, en restant toujours dans la durée réelle de la vidéo.
    function buildCandidates(dur){
      const pts = [20, 25, 30, 15, 10, 5, dur*0.5, dur*0.75, dur*0.25, 1];
      return [...new Set(pts.map(t=> Math.max(0.3, Math.min(t, Math.max(dur-0.3,0.3)))).map(t=>Math.round(t*10)/10))];
    }
    function averageBrightness(canvas){
      const ctx = canvas.getContext('2d');
      const w = canvas.width, h = canvas.height;
      const sampleW = Math.min(w,60), sampleH = Math.min(h,60);
      let data;
      try{ data = ctx.getImageData(0,0,w,h).data; }catch(e){ return 255; /* évite de bloquer si lecture impossible */ }
      let total=0, count=0;
      const stepX = Math.max(1, Math.floor(w/sampleW)), stepY = Math.max(1, Math.floor(h/sampleH));
      for(let y=0;y<h;y+=stepY){
        for(let x=0;x<w;x+=stepX){
          const i = (y*w+x)*4;
          total += (data[i]+data[i+1]+data[i+2])/3;
          count++;
        }
      }
      return count ? total/count : 255;
    }

    let candidates = [];
    let candIdx = 0;
    let bestPoster = null, bestBrightness = -1;

    function tryNext(){
      if(candIdx >= candidates.length){
        finish(bestPoster);
        return;
      }
      vid.currentTime = candidates[candIdx++];
    }
    function finish(poster){
      const secs = Math.round(vid.duration||0);
      fileData = { file:f, duration:secs, poster, name:f.name };
      document.getElementById('fileName').textContent = `Sélectionné : ${f.name} · ${formatDuration(secs)}`;
      URL.revokeObjectURL(objectUrl);
    }

    vid.addEventListener('loadeddata', ()=>{
      const dur = vid.duration || 0;
      const auto = vid.videoWidth >= vid.videoHeight ? 'landscape' : 'portrait';
      orientation = auto;
      document.querySelectorAll('.or-btn').forEach(b=>b.classList.toggle('active', b.dataset.or===auto));
      candidates = buildCandidates(dur);
      tryNext();
    });
    vid.addEventListener('seeked', ()=>{
      // Double requestAnimationFrame : laisse le temps au navigateur de peindre
      // réellement l'image avant de la capturer (sinon on récupère souvent une image noire).
      requestAnimationFrame(()=> requestAnimationFrame(()=>{
        const canvas = document.createElement('canvas');
        canvas.width = vid.videoWidth; canvas.height = vid.videoHeight;
        canvas.getContext('2d').drawImage(vid,0,0);
        const brightness = averageBrightness(canvas);
        const poster = canvas.toDataURL('image/jpeg',0.6);
        if(brightness > bestBrightness){ bestBrightness = brightness; bestPoster = poster; }
        // Assez lumineuse (pas noire) ou plus de candidats à tester → on garde la meilleure trouvée.
        if(brightness > 28 || candIdx >= candidates.length){
          finish(bestPoster);
        } else {
          tryNext();
        }
      }));
    });
  });

  function formatDuration(secs){ secs=Math.round(secs||0); const m=Math.floor(secs/60), s=secs%60; return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0'); }
  function setDefaultDatetime(){ const now=new Date(); now.setMinutes(now.getMinutes()-now.getTimezoneOffset()); document.getElementById('publishedAt').value = now.toISOString().slice(0,16); }
  setDefaultDatetime();
  function setArticleDefaultDatetime(){ const now=new Date(); now.setMinutes(now.getMinutes()-now.getTimezoneOffset()); document.getElementById('articlePublishedAt').value = now.toISOString().slice(0,16); }
  setArticleDefaultDatetime();
  function computeStatus(item){
    if(item.status==='draft') return 'draft';
    return new Date(item.publishedAt) > new Date() ? 'scheduled' : 'published';
  }
  function isPublicItem(v){ return computeStatus(v)==='published'; }

  function formatViews(n){ n=Number(n)||0; if(n>=1000000) return (n/1000000).toFixed(1).replace('.0','')+'M'; if(n>=1000) return (n/1000).toFixed(1).replace('.0','')+'K'; return String(n); }
  function formatDateFr(iso){ const d=new Date(iso); return d.toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'numeric'}) + ' · ' + d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}); }
  function escapeHtml(s){ return String(s||'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

